-- Syllable Rush: a fragment appears, the player whose turn it is types any
-- word containing it before the clock runs out. Miss and you lose a life;
-- last player standing takes the round. The turn clock shrinks as the round
-- goes on, so a bout that starts comfortable ends frantic.
--
-- Word data
-- ---------
-- syllable_words is the dictionary a submission is checked against, and
-- syllable_prompts holds the fragments. Both are derived from open data:
--
--   * Word frequencies: hermitdave/FrequencyWords (MIT), 2018 lists, which
--     rank words by how often they appear in OpenSubtitles.
--   * English spellcheck: dwyl/english-words (Unlicense, public domain),
--     used to drop the names and misspellings a subtitle corpus is full of.
--
-- Every fragment is guaranteed solvable: it is only kept when at least
-- MIN_WORDS of the most common words in that language contain it, and the
-- three most common of those are stored alongside it so a player who runs
-- out of time can be shown what they missed.

create table if not exists syllable_words (
  id uuid primary key default gen_random_uuid(),

  language text not null
    check (language in ('en', 'de')),

  word text not null,

  created_at timestamptz not null default now(),

  unique (language, word)
);

create table if not exists syllable_prompts (
  id uuid primary key default gen_random_uuid(),

  language text not null
    check (language in ('en', 'de')),

  -- The letters a submitted word has to contain.
  fragment text not null,

  -- How many common words contain it. Low is hard, high is easy.
  word_count int not null,

  -- Shown after a miss, so the round teaches rather than only punishes.
  examples text[] not null,

  active boolean not null default true,

  created_at timestamptz not null default now(),

  unique (language, fragment),

  constraint syllable_prompts_examples_check
    check (array_length(examples, 1) between 1 and 3)
);

create table if not exists syllable_sessions (
  id uuid primary key default gen_random_uuid(),
  room_id uuid not null references rooms(id) on delete cascade,

  status text not null default 'playing'
    check (status in ('playing', 'finished')),

  created_at timestamptz not null default now(),
  finished_at timestamptz
);

create table if not exists syllable_rounds (
  id uuid primary key default gen_random_uuid(),
  room_id uuid not null references rooms(id) on delete cascade,
  session_id uuid not null references syllable_sessions(id) on delete cascade,

  round_number int not null,

  status text not null default 'playing'
    check (status in ('playing', 'reveal', 'finished')),

  prompt_id uuid references syllable_prompts(id),

  current_player_id uuid references players(id) on delete set null,

  -- Counts up across the whole round; what the shrinking clock is derived
  -- from, and what orders the turn history.
  turn_number int not null default 1,

  -- Seconds allowed for the current turn, already shrunk.
  turn_seconds int not null,

  turn_ends_at timestamptz,

  created_at timestamptz not null default now(),

  unique (session_id, round_number)
);

-- One row per player per round: their lives, and whether they are out.
create table if not exists syllable_players (
  id uuid primary key default gen_random_uuid(),
  round_id uuid not null references syllable_rounds(id) on delete cascade,
  player_id uuid not null references players(id) on delete cascade,

  lives int not null default 3,
  is_out boolean not null default false,

  -- Fixed seat order, so the turn rotation is stable while players drop out.
  seat int not null,

  created_at timestamptz not null default now(),

  unique (round_id, player_id),
  unique (round_id, seat)
);

-- Every attempt, kept because it is both the history the screen shows and
-- the record of which words are already spent this round.
create table if not exists syllable_turns (
  id uuid primary key default gen_random_uuid(),
  round_id uuid not null references syllable_rounds(id) on delete cascade,
  player_id uuid not null references players(id) on delete cascade,

  turn_number int not null,

  fragment text not null,

  -- Null when the turn timed out with nothing accepted.
  word text,

  outcome text not null
    check (outcome in ('solved', 'timeout')),

  created_at timestamptz not null default now(),

  unique (round_id, turn_number)
);

create index if not exists syllable_words_lookup_idx
  on syllable_words (language, word);

create index if not exists syllable_prompts_language_idx
  on syllable_prompts (language, word_count);

create index if not exists syllable_rounds_session_idx
  on syllable_rounds (session_id);

create index if not exists syllable_players_round_idx
  on syllable_players (round_id);

create index if not exists syllable_turns_round_idx
  on syllable_turns (round_id);

alter table syllable_words enable row level security;
alter table syllable_prompts enable row level security;
alter table syllable_sessions enable row level security;
alter table syllable_rounds enable row level security;
alter table syllable_players enable row level security;
alter table syllable_turns enable row level security;

create policy "Anyone can read Syllable words"
  on syllable_words for select
  using (true);

create policy "Anyone can read Syllable prompts"
  on syllable_prompts for select
  using (true);

create policy "Anyone can manage Syllable sessions"
  on syllable_sessions for all
  using (true)
  with check (true);

create policy "Anyone can manage Syllable rounds"
  on syllable_rounds for all
  using (true)
  with check (true);

create policy "Anyone can manage Syllable players"
  on syllable_players for all
  using (true)
  with check (true);

create policy "Anyone can manage Syllable turns"
  on syllable_turns for all
  using (true)
  with check (true);

alter publication supabase_realtime add table syllable_sessions;
alter publication supabase_realtime add table syllable_rounds;
alter publication supabase_realtime add table syllable_players;
alter publication supabase_realtime add table syllable_turns;


